#!/usr/bin/env python3
"""Serialise manually authored source verdicts. No keyword/heading verdict logic.

The records below were authored after full Pro/Codex and doubt-table reading.
The N-to-entry conversion only records the supplied index's unusual grouping.
"""
import json,csv
from pathlib import Path
P=Path(__file__).resolve().parent
items=[]
EP='MPL_12_002-050'; MP='MPL_12_051-098'
def es(n):
    return f'{EP}#'+str(4 if n<=10 else 5 if n<=31 else 6 if n<=48 else 7 if n<=68 else 8 if n<=89 else 9)
def add(i,ns,kind,scans,lines,words,statement,reconstruction,check,reason,middle=()):
    sources=list(dict.fromkeys([es(n) for n in ns]+[f'{MP}#{n+12}' for n in middle]))
    items.append(dict(id=f'SA05-{i}',sources=sources,kind=kind,cote=12,scans=scans,
      lines=lines,his_words=words,statement=statement,reconstruction=reconstruction,
      check=check,check_reason=reason,subnotes=[f'{EP}:N{n:03}' for n in ns]+[f'{MP}:N{n:03}' for n in middle]))

